import { readFileSync } from "node:fs";
import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import SwatchMark from "./SwatchMark.js";

describe("SwatchMark SSR", () => {
  it("renders its colour inline on the server", () => {
    const html = renderToString(<SwatchMark colour="#e32017" />);
    expect(html).toContain('class="ds swatch-mark"');
    expect(html).toContain('aria-hidden="true"');
    expect(html).toContain("--swatch-mark-colour:#e32017");
  });

  it("names no colour of its own: the fill is the channel, the ring the muted text", () => {
    const styles = readFileSync(
      new URL("./styles.css", import.meta.url),
      "utf8",
    );
    expect(styles).toMatch(/background: var\(--swatch-mark-colour\);/);
    expect(styles).toMatch(
      /--swatch-mark-ring-color: var\(--color-text-muted\);/,
    );
    expect(styles).not.toMatch(/#[0-9a-f]{3,8}\b|rgb\(|hsl\(/i);
  });
});
